function go(path: string) {
  window.history.pushState({}, '', path)
  window.dispatchEvent(new PopStateEvent('popstate'))
}

function tagClass(value: string) {
  return value.includes('失败') || value.includes('取消') || value.includes('缺货') || value.includes('异常') ? 'bad' : value.includes('待') || value.includes('关注') || value.includes('运行') || value.includes('处理中') ? 'warn' : value.includes('健康') || value.includes('完成') || value.includes('发货') || value.includes('送达') || value.includes('已入账') || value.includes('可下载') ? 'good' : ''
}

function StatusTag({ value }: { value: string }) {
  return <span className={`tag ${tagClass(value)}`}><i className="status-dot" />{value}</span>
}

function Chart() {
  const ref = useRef<HTMLDivElement>(null)
  useEffect(() => {
    if (!ref.current) return
    const chart = echarts.init(ref.current)
    chart.setOption({ grid: { left: 12, right: 14, top: 18, bottom: 28, containLabel: true }, tooltip: { trigger: 'axis' }, xAxis: { type: 'category', data: ['10/11', '10/12', '10/13', '10/14', '10/15', '10/16', '10/17'], axisLine: { lineStyle: { color: '#e7ecf2' } }, axisLabel: { color: '#98a2b3' } }, yAxis: { type: 'value', splitLine: { lineStyle: { color: '#f0f2f5' } }, axisLabel: { color: '#98a2b3' } }, series: [{ name: '销售额', type: 'line', smooth: true, data: [41200, 46800, 44500, 52900, 68200, 72400, 85120], lineStyle: { color: '#3675f5', width: 3 }, itemStyle: { color: '#3675f5' }, areaStyle: { color: 'rgba(54,117,245,.08)' } }] })
    const onResize = () => chart.resize()
    window.addEventListener('resize', onResize)
    return () => { window.removeEventListener('resize', onResize); chart.dispose() }
  }, [])
  return <div ref={ref} className="chart-box" />
}

