function LoginPage() {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [busy, setBusy] = useState(false)
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); try { await login(email, password); go('/app/overview') } catch (error) { Message.error(error instanceof Error ? error.message : '登录失败') } finally { setBusy(false) } }
  return <div className="login-page"><div className="login-copy"><div className="eyebrow">NOVA ERP WORKSPACE</div><h1>把多主体经营，放进一个清晰工作台。</h1><p>统一管理店铺、订单、退款、库存、财务与广告数据，让每一次查看、授权和导出都有明确边界。</p><div className="login-benefits"><div className="login-benefit"><IconCheckCircle /><span><b>按主体和店铺隔离数据</b><br /><small>成员只查看被授权的经营范围</small></span></div><div className="login-benefit"><IconCheckCircle /><span><b>Seller 与 Ads 分开授权</b><br /><small>连接状态、同步任务和异常可追踪</small></span></div><div className="login-benefit"><IconCheckCircle /><span><b>导出、权限、操作全程留痕</b><br /><small>敏感动作进入企业审计记录</small></span></div></div></div><form className="login-card" onSubmit={submit}><div className="brand"><span className="brand-mark">N</span><span>企业工作台</span></div><h2>登录 ERP 工作台</h2><p className="sub">使用已配置的企业账号进入经营管理空间</p><label htmlFor="email">企业邮箱</label><input id="email" type="email" value={email} onChange={e => setEmail(e.target.value)} placeholder="name@company.com" autoComplete="username" required /><label htmlFor="password">登录密码</label><input id="password" type="password" value={password} onChange={e => setPassword(e.target.value)} placeholder="请输入密码" autoComplete="current-password" required /><button className="primary-button login-submit" disabled={busy}>{busy ? '正在登录…' : '登录工作台  →'}</button><div className="login-note">生产环境仅接受已初始化的企业账号，首次账号由服务器管理员安全创建。</div></form></div>
}

function Shell({ path, children }: { path: string; children: ReactNode }) {
  const [searchOpen, setSearchOpen] = useState(false)
  const [me, setMe] = useState<{ user?: { displayName?: string; email?: string }; tenant?: { name?: string } } | null>(null)
  useEffect(() => { const listener = (event: KeyboardEvent) => { if ((event.ctrlKey || event.metaKey) && event.key.toLowerCase() === 'k') { event.preventDefault(); setSearchOpen(true) } if (event.key === 'Escape') setSearchOpen(false) }; window.addEventListener('keydown', listener); return () => window.removeEventListener('keydown', listener) }, [])
  useEffect(() => { let alive = true; void apiFetch<typeof me>('/auth/me').then(value => { if (alive) setMe(value) }).catch(() => undefined); return () => { alive = false } }, [])
  const displayName = me?.user?.displayName ?? '当前用户'
  const tenantName = me?.tenant?.name ?? '当前企业'
  return <div className="app-shell"><aside className="app-sidebar"><div className="app-brand"><div className="brand"><span className="brand-mark">N</span><span>NOVA ERP</span></div><small>ENTERPRISE WORKSPACE</small></div><nav className="app-nav">{navGroups.map(group => <div key={group.label}><div className="nav-label">{group.label}</div>{group.items.map(([href, label, Icon]) => <button key={href} className={`nav-item ${path === href ? 'active' : ''}`} onClick={() => go(href)}><Icon />{label}</button>)}</div>)}<div className="nav-label">账户</div><button className={`nav-item ${path === '/app/profile' ? 'active' : ''}`} onClick={() => go('/app/profile')}><IconUser />个人账号</button></nav><div className="sidebar-footer"><span><i className="status-dot" />{isServerMode ? '生产 API' : '服务端未配置'}</span><small>企业数据 · 权限隔离</small><button className="link-button" onClick={() => go('/site')}>官网首页 <IconArrowRight /></button></div></aside><div className="app-main"><header className="app-topbar"><div className="topbar-left"><span className="crumb">NOVA ERP / {pageNames[path]?.[0] ?? '工作台'}</span><button className="global-search" onClick={() => setSearchOpen(true)}><IconSearch /><span>搜索功能模块或进入页面</span><kbd>Ctrl K</kbd></button></div><div className="top-actions"><span className="status-note"><i className="status-dot" />{isServerMode ? '生产 API' : '服务端未配置'}</span><button className="tenant-select" onClick={() => Message.info(`当前企业：${tenantName}`)}>{tenantName} ▾</button><button className="icon-button" aria-label="打开审计中心" onClick={() => go('/app/audit')}><IconNotification /></button><button className="profile-chip" onClick={() => go('/app/profile')}><span className="brand-mark">{displayName.slice(0, 1)}</span><span>{displayName}</span></button></div></header>{children}</div>{searchOpen && <CommandPalette onClose={() => setSearchOpen(false)} />}</div>
}

function CommandPalette({ onClose }: { onClose: () => void }) {
  const [query, setQuery] = useState('')
  const items = allNavItems.filter(([, label]) => label.includes(query) || query.length === 0).slice(0, 8)
  return <div className="command-backdrop" onClick={onClose}><div className="command-palette" onClick={event => event.stopPropagation()}><div className="command-input"><IconSearch /><input autoFocus value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索功能模块…" /><kbd>ESC</kbd></div><div className="command-hint">功能导航</div>{items.map(([href, label, Icon]) => <button key={href} className="command-item" onClick={() => { onClose(); go(href) }}><Icon /><span>{label}</span><small>{pageNames[href]?.[1]}</small><IconArrowRight /></button>)}{items.length === 0 && <div className="empty">没有匹配的功能</div>}<div className="command-footer">↑↓ 选择 · Enter 打开 · Esc 关闭</div></div></div>
}

function NotificationDrawer({ onClose }: { onClose: () => void }) {
  return <div className="drawer-backdrop" onClick={onClose}><aside className="drawer notification-drawer" onClick={event => event.stopPropagation()}><div className="drawer-head"><div><h2>通知中心</h2><small>3 条待处理事项</small></div><button className="close-button" onClick={onClose}>×</button></div><div className="notification-list"><div className="notification-item unread"><i className="status-dot warn" /><div><b>Northstar DE 同步需要检查</b><p>财务事件任务在 10:14 失败，建议查看错误原因后重试。</p><small>12 分钟前 · 同步任务</small></div></div><div className="notification-item unread"><i className="status-dot" /><div><b>广告报表已生成</b><p>Search Term Report 已可下载，链接将在 24 小时后失效。</p><small>28 分钟前 · 广告报表</small></div></div><div className="notification-item"><i className="status-dot" /><div><b>库存快照同步完成</b><p>Northstar UK 已更新 1,286 个 SKU 的库存快照。</p><small>1 小时前 · 库存工作台</small></div></div></div><button className="outline-button" style={{ width: '100%', marginTop: 18 }} onClick={() => { onClose(); go('/app/audit') }}>查看全部通知与记录</button></aside></div>
}

function PageTitle({ path, action }: { path: string; action?: ReactNode }) {
  const resolvedPath = path === '/app/products' && window.location.pathname === '/app/supply-chain' ? '/app/supply-chain' : path
  const [title, desc] = pageNames[resolvedPath] ?? ['工作台', '企业经营空间']
  return <div className="page-title"><div><div className="page-context"><span>企业工作区</span><i>/</i><span>{title}</span></div><h1>{title}</h1><p>{desc} · 数据更新时间 2026-10-17 10:46</p></div><div className="title-actions">{action ?? <><button className="outline-button" onClick={() => Message.success('已刷新当前工作区数据')}><IconRefresh /> 刷新</button><button className="blue-button" onClick={() => Message.info('已打开任务创建流程')}><IconPlus /> 新建任务</button></>}</div></div>
}

function Metric({ label, value, trend, warn }: { label: string; value: string; trend: string; warn?: boolean }) { return <div className="metric"><small>{label}</small><strong>{value}</strong><em className={warn ? 'warn' : ''}>{trend}</em></div> }
function KpiStrip({ items }: { items: Array<{ label: string; value: string; trend: string; warn?: boolean }> }) { return <div className="metrics">{items.map(item => <Metric key={item.label} {...item} />)}</div> }

function OrderTable({ rows }: { rows: Order[] }) { return <table className="data-table" aria-label="最近订单"><thead><tr><th>订单编号</th><th>店铺 / 站点</th><th>下单时间</th><th>金额</th><th>履约</th><th>状态</th></tr></thead><tbody>{rows.map(row => <tr key={row.id}><td><span className="id-text">{row.id}</span></td><td>{row.store} · {row.marketplace}</td><td>{row.purchasedAt}</td><td>{row.currency} {row.amount}</td><td>{row.fulfillment}</td><td><StatusTag value={row.status} /></td></tr>)}</tbody></table> }

function OverviewPage() { return <div className="page-body"><PageTitle path="/app/overview" /><KpiStrip items={[{ label: '近30天销售额', value: '$486,920.40', trend: '+12.8% 较上周期' }, { label: '订单数', value: '12,840', trend: '+8.4% 较上周期' }, { label: '广告花费', value: '$42,180.20', trend: 'ACOS 18.6%' }, { label: '店铺健康度', value: '96.4%', trend: '4 个店铺 · 1 个待处理', warn: true }]} /><div className="content-grid"><div><div className="panel"><div className="panel-head"><h3>销售趋势</h3><span>USD · 近 7 天 · 订单与退款汇总</span></div><Chart /></div><div className="table-panel"><div className="table-head"><h3>最近订单</h3><button className="link-button" onClick={() => go('/app/orders')}>查看全部 <IconArrowRight /></button></div><OrderTable rows={orders.slice(0, 4)} /></div></div><div><div className="panel"><div className="panel-head"><h3>连接健康</h3><span>实时检查</span></div><div className="health-list">{stores.map(store => <div className="health-row" key={store.id}><div className="health-name"><i className={`status-dot ${store.health === '待处理' ? 'warn' : ''}`} />{store.name}</div><small>{store.lastSync}</small><StatusTag value={store.health} /></div>)}</div></div><div className="panel"><div className="panel-head"><h3>待处理事项</h3><span>本企业</span></div><div className="quick-list"><div className="quick-row"><span>待发货订单</span><b>184</b></div><div className="quick-row"><span>库存补货风险</span><b style={{ color: 'var(--amber)' }}>12</b></div><div className="quick-row"><span>失败同步任务</span><b style={{ color: 'var(--red)' }}>1</b></div><div className="quick-row"><span>即将过期导出</span><b>3</b></div></div></div></div></div></div> }

function OrdersPage() { const [selected, setSelected] = useState<Order | null>(null); const [query, setQuery] = useState(''); const rows = useMemo(() => orders.filter(row => `${row.id}${row.store}${row.status}`.toLowerCase().includes(query.toLowerCase())), [query]); return <div className="page-body"><PageTitle path="/app/orders" action={<><button className="outline-button" onClick={() => Message.info('已创建订单导出任务')}><IconFile /> 导出</button><button className="blue-button" onClick={() => Message.success('订单同步任务已加入队列')}><IconRefresh /> 同步订单</button></>} /><div className="filter-bar"><IconSearch /><input value={query} onChange={event => setQuery(event.target.value)} placeholder="搜索订单号、店铺或状态" /><select defaultValue="全部站点"><option>全部站点</option><option>US</option><option>UK</option><option>DE</option></select><select defaultValue="近30天"><option>近30天</option><option>近7天</option><option>本月</option></select><button className="outline-button" onClick={() => Message.info('已展开更多订单筛选条件')}>筛选条件</button></div><KpiStrip items={[{ label: '全部订单', value: '12,840', trend: '近30天' }, { label: '待发货', value: '184', trend: '需要关注', warn: true }, { label: '已发货', value: '11,992', trend: '93.4%' }, { label: '取消率', value: '0.52%', trend: '-0.08%' }]} /><div className="table-panel"><div className="table-head"><h3>订单明细 <span className="table-count">共 {rows.length} 条示例记录</span></h3><div className="status-note"><i className="status-dot" />数据已同步</div></div><div className="table-scroll"><table className="data-table"><thead><tr><th>订单编号</th><th>店铺</th><th>Marketplace</th><th>下单时间</th><th>金额</th><th>件数</th><th>履约</th><th>状态</th></tr></thead><tbody>{rows.map(row => <tr data-id={row.id} key={row.id} onClick={() => setSelected(row)}><td><span className="id-text">{row.id}</span></td><td>{row.store}</td><td>{row.marketplace}</td><td>{row.purchasedAt}</td><td>{row.currency} {row.amount}</td><td>{row.items}</td><td>{row.fulfillment}</td><td><StatusTag value={row.status} /></td></tr>)}</tbody></table></div></div>{selected && <OrderDrawer order={selected} onClose={() => setSelected(null)} />}</div> }

