  const replenishment = inventory.map((row, index) => ({ ...row, forecast: index === 3 ? '5 天' : index === 1 ? '8 天' : `${row.days} 天`, suggested: index === 3 ? '720' : index === 1 ? '1,200' : index === 2 ? '480' : '—', owner: index < 2 ? '待采购确认' : '供应链组' }))
  return <div className="page-body inventory-control"><PageTitle path="/app/inventory" action={<><button className="outline-button" onClick={() => Message.info('库存导出任务已创建')}><IconFile /> 导出</button><button className="blue-button" onClick={() => go('/app/supply-chain')}><IconPlus /> 创建采购单</button></>} /><div className="module-context"><div><small>库存口径</small><b>可售 = 可售库存 - 预留数量</b></div><div><small>覆盖范围</small><b>4 个店铺 · 3 个仓库</b></div><div><small>计算时间</small><b><i className="status-dot" /> 10:44 完成</b></div><button className="link-button" onClick={() => go('/app/warehouse')}>查看仓库作业 <IconArrowRight /></button></div><div className="inventory-command"><div><span className="eyebrow">REPLENISHMENT CONTROL</span><h2>补货控制台</h2><p>先处理缺货风险，再处理库存效率。每一条建议都有销售速度、在途和负责人。</p></div><div className="inventory-kpi"><div><b>12</b><span>需立即处理</span></div><div><b>22</b><span>采购批次</span></div><div><b>6,840</b><span>在途数量</span></div></div></div><div className="inventory-grid"><section className="table-panel"><div className="table-head"><div><h3>补货决策列表</h3><span className="table-subtitle">建议数量需经过采购负责人确认后才会创建采购单</span></div><div className="filter-inline"><select defaultValue="全部风险"><option>全部风险</option><option>缺货风险</option><option>需补货</option><option>健康</option></select></div></div><div className="table-scroll"><table className="data-table"><thead><tr><th>产品对象</th><th>店铺</th><th>库存结构</th><th>预测可售</th><th>建议补货</th><th>负责人</th><th>状态</th><th>动作</th></tr></thead><tbody>{replenishment.map(row => <tr key={row.sku} className={row.status === '缺货风险' || row.status === '需补货' ? 'risk-row' : ''}><td><b className="id-text">{row.sku}</b><small className="cell-sub">{row.title}</small></td><td>{row.store}</td><td><div className="stock-stack"><span>可售 <b>{row.available.toLocaleString()}</b></span><span>在途 <b>{row.inbound.toLocaleString()}</b></span><span>预留 <b>{row.reserved}</b></span></div></td><td><b className={row.days < 10 ? 'danger-text' : ''}>{row.forecast}</b></td><td>{row.suggested === '—' ? '—' : <b>{row.suggested} 件</b>}</td><td>{row.owner}</td><td><StatusTag value={row.status} /></td><td><button className="link-button" onClick={() => setSelected(row.sku)}>{row.suggested === '—' ? '加入观察' : '发起审批'}</button></td></tr>)}</tbody></table></div></section><aside className="panel approval-panel"><div className="panel-head"><div><h3>待审批动作</h3><span>需要明确负责人</span></div><b className="approval-count">2</b></div><div className="approval-list"><div><span className="approval-type">采购建议</span><b>NS-LAMP-04</b><small>建议补货 720 件 · 东莞光源制造</small><button className="blue-button" onClick={() => Message.success('补货建议已批准并生成采购草稿')}>批准</button><button className="link-button" onClick={() => Message.info('已转交供应链负责人')}>转交</button></div><div><span className="approval-type">采购建议</span><b>NS-BAG-02-BLK</b><small>建议补货 1,200 件 · 深圳南星供应链</small><button className="blue-button" onClick={() => Message.success('补货建议已批准并生成采购草稿')}>批准</button><button className="link-button" onClick={() => Message.info('已转交供应链负责人')}>转交</button></div></div><div className="approval-footer"><span>审批动作将写入审计中心</span><button className="link-button" onClick={() => go('/app/audit')}>查看记录</button></div></aside></div>{selected && <div className="drawer-backdrop" onClick={() => setSelected(null)}><aside className="drawer" onClick={event => event.stopPropagation()}><div className="drawer-head"><div><span className="eyebrow">INVENTORY DECISION</span><h2>{selected}</h2><small>补货建议详情</small></div><button className="close-button" onClick={() => setSelected(null)}>×</button></div><div className="notice">正式执行前需要负责人确认数量、供应商、目的仓和预计到仓日期。</div><div className="drawer-section"><h3>决策字段</h3><dl className="detail-grid"><dt>建议数量</dt><dd>720 件</dd><dt>预测可售</dt><dd>5 天</dd><dt>目的仓</dt><dd>FBA-LHR-02 · UK London</dd><dt>建议供应商</dt><dd>东莞光源制造</dd><dt>授权范围</dt><dd>Northstar Trading Ltd.</dd></dl></div><div className="drawer-actions"><button className="outline-button" onClick={() => Message.info('已保存为观察项')}>暂不处理</button><button className="blue-button" onClick={() => Message.success('已批准，采购草稿已创建')}>批准并创建采购单</button></div></aside></div>}</div>
